{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-08",
  "sketch": {
    "components": ["Support admin console", "\"Log in as customer\" endpoint", "Session issuance service", "Customer web app", "Role/permission store"],
    "dataStores": ["Session store", "Customer account records"],
    "externalServices": [],
    "trustBoundaries": ["Employee support role to customer account boundary", "Admin console to customer-facing session boundary"],
    "dataClasses": ["pii", "credentials"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "ElevationOfPrivilege",
      "title": "Every support employee can take over any customer account with one click",
      "scenario": "The design grants impersonation to the whole support role with no per-case authorisation, no customer consent and no approval step. Any of potentially hundreds of employees (or anyone who phishes one support login) can select an arbitrary customer and operate as them: read their data, change settings, place or cancel orders. A single low-privileged insider or one compromised support account becomes full access to the entire customer base.",
      "component": "\"Log in as customer\" endpoint",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "It is available to every employee with the support role." }
      ],
      "asvs": ["V8.1.1", "V8.2.1"],
      "cwe": ["CWE-269", "CWE-862"],
      "plainLanguage": "Anyone on the support team can log in as any customer, so one misused or stolen support account exposes everybody.",
      "requirement": {
        "title": "Gate impersonation behind a narrow permission and an authorised case",
        "given": "an employee holds the support role",
        "when": "they request to log in as a customer",
        "then": "the server only issues the session if the employee holds a separate impersonation permission and the request is tied to an open support case for that specific customer, otherwise it is denied"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Impersonation session can be used to change credentials and permanently seize the account",
      "scenario": "Because the admin receives an ordinary customer session, nothing stops them using sensitive self-service flows: change email, change password, disable MFA, add a payout or shipping destination. A support employee can therefore convert a temporary look-at-the-account session into permanent control of the customer's account and any money or data behind it, long after the support interaction ends.",
      "component": "Customer web app under impersonated session",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "The feature issues a customer session to the admin." }
      ],
      "asvs": ["V8.1.1", "V6.3.1"],
      "cwe": ["CWE-269", "CWE-640"],
      "plainLanguage": "While logged in as the customer, support staff could change the password or email and keep the account for themselves.",
      "requirement": {
        "title": "Make impersonated sessions read-mostly and block credential changes",
        "given": "a session was created through impersonation",
        "when": "a request hits a credential, MFA, email, payment-instrument or account-deletion endpoint",
        "then": "the server rejects the request because the session is flagged as impersonated, regardless of the user's own rights"
      }
    },
    {
      "stride": "Repudiation",
      "title": "Actions taken while impersonating look like the customer's own actions",
      "scenario": "The session handed to the admin is a customer session, so requests, records and any existing logs are attributed to the customer with no marker of which employee was driving. If a support employee commits fraud or an angry customer disputes a change, there is no way to prove who acted. Investigation and any deterrent effect disappear, which is what makes abuse of this feature attractive in the first place.",
      "component": "Session issuance service",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "The feature issues a customer session to the admin." }
      ],
      "asvs": ["V16.2.1", "V7.1.1"],
      "cwe": ["CWE-778"],
      "plainLanguage": "Anything support staff do while pretending to be a customer is recorded as the customer doing it, so nobody can tell who really did it.",
      "requirement": {
        "title": "Bind the acting employee to every impersonated request",
        "given": "an impersonated session is active",
        "when": "any request is handled",
        "then": "the session carries both the impersonated customer id and the acting employee id, and every log and audit record stores both"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Hijacked or tricked admin browser can mint a customer session",
      "scenario": "The feature is a click in the admin UI with no described step-up re-authentication. An attacker who steals a support employee's session cookie, or who gets them to load a crafted page that triggers the impersonation request, can mint sessions for chosen customers without ever knowing the employee's password or second factor. The attacker then browses customer accounts from their own machine.",
      "component": "\"Log in as customer\" endpoint",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "Support admins can click \"log in as customer\" to see exactly what a customer sees." }
      ],
      "asvs": ["V6.2.1", "V3.4.1"],
      "cwe": ["CWE-352", "CWE-384"],
      "plainLanguage": "Someone who steals a support worker's browser session, or tricks their browser, could create customer logins without knowing their password.",
      "requirement": {
        "title": "Require step-up authentication and anti-CSRF on impersonation",
        "given": "an authenticated support employee",
        "when": "the impersonation endpoint is called",
        "then": "the call is rejected unless it carries a valid anti-CSRF token and a fresh multi-factor re-authentication completed within a short window"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Unrestricted browsing of any customer's personal data",
      "scenario": "The stated goal is to see exactly what the customer sees, which includes their personal details, order history, addresses and stored payment metadata. With no scoping to a specific ticket and no limit on how many customers one employee may view, a curious or malicious employee can walk through high-profile or arbitrary accounts, or script repeated impersonations to harvest personal data at scale.",
      "component": "Customer web app under impersonated session",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "Support admins can click \"log in as customer\" to see exactly what a customer sees." }
      ],
      "asvs": ["V8.1.1", "V14.1.1"],
      "cwe": ["CWE-359", "CWE-1230"],
      "plainLanguage": "Support staff can snoop through any customer's private details, including celebrities or exes, and nothing limits how many they look at.",
      "requirement": {
        "title": "Limit and alert on impersonation volume and target choice",
        "given": "an employee has already impersonated customers recently",
        "when": "they exceed a configured number of distinct customers in a time window, or target an account flagged as sensitive",
        "then": "the request is blocked pending a second approver and a security alert is raised"
      }
    },
    {
      "stride": "Tampering",
      "title": "Attacker-chosen target id lets impersonation reach privileged or staff accounts",
      "scenario": "The impersonation request must name which customer to become. If the server trusts that identifier without checking that the target really is a customer in the requester's support scope, an employee can substitute the id of an internal, test, finance or administrator account and receive a session for it, escalating from support-level access to full application control.",
      "component": "\"Log in as customer\" endpoint",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "The feature issues a customer session to the admin." }
      ],
      "asvs": ["V8.2.1", "V4.1.1"],
      "cwe": ["CWE-639", "CWE-266"],
      "plainLanguage": "By changing the customer number in the request, support staff might log in as an admin instead of a customer.",
      "requirement": {
        "title": "Validate the impersonation target server-side",
        "given": "an impersonation request naming a target account id",
        "when": "the server resolves the target",
        "then": "it issues a session only if the target is an end-customer account with no staff or elevated roles, and denies all other targets"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Impersonated sessions outlive the support interaction",
      "scenario": "A normal customer session is typically long-lived and renewable. Handing one to an admin means the borrowed access does not end when the call or ticket ends; the employee can return to the customer's account days later, and the customer has no way to see or end the session. Access intended for a few minutes becomes standing access to that account.",
      "component": "Session store",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "The feature issues a customer session to the admin." }
      ],
      "asvs": ["V7.3.1", "V7.4.1"],
      "cwe": ["CWE-613"],
      "plainLanguage": "The borrowed customer login does not expire when the support call ends, so staff can come back later.",
      "requirement": {
        "title": "Short-lived, revocable impersonated sessions",
        "given": "an impersonated session has been issued",
        "when": "a short absolute timeout passes, the employee ends impersonation, or the customer or an admin revokes it",
        "then": "the session is invalidated server-side and cannot be renewed or refreshed"
      }
    },
    {
      "stride": "Repudiation",
      "title": "Customer is never told their account was accessed by staff",
      "scenario": "Nothing in the design notifies the customer or shows impersonation in their account activity, and the admin sees exactly the normal customer view. A support employee can access an account and, because the customer never learns of it, abuse goes undetected until damage surfaces. Lack of visibility also makes it impossible for the customer to challenge changes made in their name.",
      "component": "Customer web app under impersonated session",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "Support admins can click \"log in as customer\" to see exactly what a customer sees." }
      ],
      "asvs": ["V16.2.1"],
      "cwe": ["CWE-778"],
      "plainLanguage": "Customers never find out that a staff member logged into their account.",
      "requirement": {
        "title": "Surface impersonation to the customer",
        "given": "an impersonated session has been used on a customer account",
        "when": "the session ends",
        "then": "the event appears in the customer's own account activity list with the time and reason, and a notification is sent for sensitive accounts or sensitive actions"
      }
    }
  ]
}
